param([Parameter(Mandatory=$true)][string]$Version,[Parameter(Mandatory=$true)][string]$Bundle,[Parameter(Mandatory=$true)][string]$Signature,[Parameter(Mandatory=$true)][string]$Repository,[string]$Tag="v$Version")
$ErrorActionPreference="Stop";$name=Split-Path $Bundle -Leaf;$sig=(Get-Content $Signature -Raw).Trim();$latest=[ordered]@{version=$Version;notes="Release $Version";pub_date=(Get-Date).ToUniversalTime().ToString("o");platforms=@{"windows-x86_64"=@{signature=$sig;url="https://github.com/$Repository/releases/download/$Tag/$name"}}};$latest|ConvertTo-Json -Depth 5|Set-Content latest-rust.json -Encoding utf8
